"""CLI entry point: prints the cart total in cents for a JSON cart file."""

import json
import sys

import cart_core


def main(argv):
    if len(argv) != 2:
        print(f"usage: {argv[0]} <cart.json>", file=sys.stderr)
        return 2
    path = argv[1]
    try:
        with open(path, encoding="utf-8") as f:
            cart = json.load(f)
    except OSError as exc:
        print(f"error: cannot read {path}: {exc}", file=sys.stderr)
        return 1
    except json.JSONDecodeError as exc:
        print(f"error: invalid JSON in {path}: {exc}", file=sys.stderr)
        return 1
    if not isinstance(cart, list):
        print(f"error: invalid cart: expected a JSON array", file=sys.stderr)
        return 1
    try:
        total = cart_core.total_cents(cart)
    except (ValueError, KeyError, TypeError) as exc:
        print(f"error: invalid cart values in {path}: {exc}", file=sys.stderr)
        return 1
    print(total)
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

