"""Core cart total logic for the offline shopping cart CLI."""


def total_cents(items):
    """Return the total price of `items` in integer cents.

    Each item must be a mapping with integer `quantity` and `unit_cents`
    (bools are rejected). Returns 0 for an empty list. Raises ValueError
    for negative or non-integer values.
    """
    total = 0
    for item in items:
        quantity = item["quantity"]
        unit_cents = item["unit_cents"]
        for name, value in (("quantity", quantity), ("unit_cents", unit_cents)):
            if isinstance(value, bool) or not isinstance(value, int):
                raise ValueError(
                    "%s must be an integer, got %r" % (name, value)
                )
            if value < 0:
                raise ValueError(
                    "%s must be non-negative, got %r" % (name, value)
                )
        total += quantity * unit_cents
    return total
